const files = {"/index.html":{"type":"text/html; charset=utf-8","data":""},"/styles.css":{"type":"text/css; charset=utf-8","data":""},"/script.js":{"type":"application/javascript; charset=utf-8","data":""},"/assets/alternates/claridad.jpg":{"type":"image/jpeg","data":""},"/assets/alternates/identidad-espejo.jpg":{"type":"image/jpeg","data":""},"/assets/barbara-beiles-photo.png":{"type":"image/png","data":""},"/assets/barbara-beiles.jpg":{"type":"image/jpeg","data":""},"/assets/hero-el-alquimista.jpg":{"type":"image/jpeg","data":""},"/assets/method/fase-1.jpg":{"type":"image/jpeg","data":""},"/assets/method/fase-2.jpg":{"type":"image/jpeg","data":""},"/assets/method/fase-3.jpg":{"type":"image/jpeg","data":""},"/assets/method/fase-4.jpg":{"type":"image/jpeg","data":""},"/assets/method/fase-5.jpg":{"type":"image/jpeg","data":""},"/assets/pillars/accion-estrategica.jpg":{"type":"image/jpeg","data":""},"/assets/pillars/identidad.jpg":{"type":"image/jpeg","data":""},"/assets/pillars/reprogramacion.jpg":{"type":"image/jpeg","data":""},"/assets/pillars/sistema-nervioso.jpg":{"type":"image/jpeg","data":""}};

function decodeBase64(base64) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

function assetResponse(pathname) {
  const file = files[pathname] || (pathname === "/" ? files["/index.html"] : null);
  if (!file) return null;

  const headers = new Headers({
    "content-type": file.type,
    "x-content-type-options": "nosniff",
  });

  if (pathname.startsWith("/assets/")) {
    headers.set("cache-control", "public, max-age=31536000, immutable");
  } else {
    headers.set("cache-control", "public, max-age=60");
  }

  return new Response(decodeBase64(file.data), { headers });
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const pathname = decodeURIComponent(url.pathname);

    const direct = assetResponse(pathname);
    if (direct) return direct;

    if (!pathname.includes(".") && request.method === "GET") {
      return assetResponse("/");
    }

    return new Response("Not found", {
      status: 404,
      headers: { "content-type": "text/plain; charset=utf-8" },
    });
  },
};
